def topological_sort(graph: dict[str, list[str]]) -> tuple[list[str], list[str] | None]:
    """Return a topological order of dependency keys, or ([], cycle) if a cycle exists."""
    all_nodes = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    state = {n: "white" for n in all_nodes}
    path = []
    cycle = None
    order = []

    def dfs(u: str) -> bool:
        nonlocal cycle, order
        state[u] = "gray"
        path.append(u)
        for v in graph.get(u, []):
            if state[v] == "gray":
                idx = path.index(v)
                cycle = path[idx:]
                return True
            if state[v] == "white":
                if dfs(v):
                    return True
        path.pop()
        state[u] = "black"
        order.append(u)
        return False

    for node in all_nodes:
        if state[node] == "white":
            if dfs(node):
                return ([], cycle)

    return (order, None)
```
